-- ── Locations (per-user cities and addresses) ─────────────────────────────────
CREATE TABLE IF NOT EXISTS locations (
    id         TEXT PRIMARY KEY,
    user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name       TEXT NOT NULL,
    alias      TEXT,
    region     TEXT,
    address    TEXT,
    type       TEXT NOT NULL CHECK(type IN ('city', 'address')),
    country_id TEXT NOT NULL REFERENCES countries(id),
    parent_id  TEXT REFERENCES locations(id) ON DELETE CASCADE,
    lat        REAL,
    lon        REAL,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX IF NOT EXISTS idx_locations_user_country ON locations(user_id, country_id);
CREATE INDEX IF NOT EXISTS idx_locations_parent ON locations(parent_id);

CREATE UNIQUE INDEX IF NOT EXISTS idx_locations_city_unique
    ON locations(user_id, country_id, LOWER(name), LOWER(COALESCE(region, '')))
    WHERE type = 'city';

CREATE UNIQUE INDEX IF NOT EXISTS idx_locations_address_unique
    ON locations(user_id, parent_id, LOWER(name))
    WHERE type = 'address';

CREATE UNIQUE INDEX IF NOT EXISTS idx_locations_alias_unique
    ON locations(user_id, LOWER(alias))
    WHERE alias IS NOT NULL;

-- ── items.location_id FK ──────────────────────────────────────────────────────
ALTER TABLE items ADD COLUMN location_id TEXT REFERENCES locations(id) ON DELETE SET NULL;
